class Solution {
public:
    string sortSentence(string s) {
        string result;
        int n = s.size();
        for (char d = '1'; d <= '9'; d++) {
            int i = 0;
            while (i < n) {
                int start = i;
                while (i < n && s[i] != ' ') i++;
                if (i > start && s[i - 1] == d) {
                    if (!result.empty()) result += ' ';
                    result.append(s, start, i - 1 - start);
                }
                if (i < n) i++;
            }
        }
        return result;
    }
};
